import * as React from 'react';

export interface StepContextProps {
  index: number;
  completed?: boolean;
  error?: boolean;
  disabled?: boolean;
}

const StepContext = React.createContext<StepContextProps | undefined>(undefined);

export function useStepContext(): StepContextProps | undefined {
  return React.useContext(StepContext);
}

export default StepContext;
